head.b:skin:
/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#059669" value="#059669"/>
<Variable name="body.background.color" description="Body background color" type="color" default="#F8FAFC" value="#F8FAFC"/>
<Variable name="body.text.color" description="Body text color" type="color" default="#1E293B" value="#1E293B"/>
<Variable name="body.link.color" description="Link color" type="color" default="#059669" value="#059669"/>
<Variable name="posts.background.color" description="Post background color" type="color" default="#ffffff" value="#ffffff"/>
*/

:root {
  --bg-main: #F8FAFC;
  --bg-card: rgba(255, 255, 255, 0.92);
  --border-subtle: rgba(226, 232, 240, 0.9);
  --border-emerald: rgba(16, 185, 129, 0.35);
  --emerald-primary: #059669;
  --emerald-fresh: #10B981;
  --cyan-fresh: #0284C7;
}

* {
  box-sizing: border-box;
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', sans-serif;
  background-color: var(--bg-main);
  color: #1E293B;
  overflow-x: hidden;
  margin: 0;
  padding: 0;
}

::selection {
  background: #A7F3D0;
  color: #064E3B;
}

.font-tech {
  font-family: 'Space Grotesk', sans-serif;
}

.font-mono {
  font-family: 'JetBrains Mono', monospace;
}

/* Fresh Light Background Patterns */
.bg-fresh-mesh {
  background: 
    radial-gradient(at 0% 0%, rgba(209, 250, 229, 0.7) 0px, transparent 50%),
    radial-gradient(at 100% 0%, rgba(224, 242, 254, 0.7) 0px, transparent 50%),
    radial-gradient(at 50% 50%, rgba(240, 253, 244, 0.5) 0px, transparent 60%),
    radial-gradient(at 100% 100%, rgba(254, 243, 199, 0.4) 0px, transparent 50%),
    #F8FAFC;
}

.bg-grid-pattern-light {
  background-size: 32px 32px;
  background-image: 
    linear-gradient(to right, rgba(148, 163, 184, 0.08) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(148, 163, 184, 0.08) 1px, transparent 1px);
}

/* Nav Item Active State Styling */
.nav-link-active {
  background-color: #059669 !important;
  color: #FFFFFF !important;
  font-weight: 700 !important;
  box-shadow: 0 4px 14px -2px rgba(5, 150, 105, 0.4);
}

.nav-link-inactive {
  color: #475569 !important;
  background-color: transparent !important;
}

.nav-link-inactive:hover {
  color: #047857 !important;
  background-color: rgba(209, 250, 229, 0.65) !important;
}

/* 3D Perspective Container */
.perspective-container {
  perspective: 1200px;
  transform-style: preserve-3d;
}

/* 3D Tilt Card */
.tilt-card {
  transform-style: preserve-3d;
  transition: transform 0.15s ease-out, box-shadow 0.3s ease;
  will-change: transform;
}

.tilt-content {
  transform: translateZ(30px);
}

.tilt-content-deep {
  transform: translateZ(55px);
}

/* 3D Phone Cards */
.phone-card-3d {
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  transform-style: preserve-3d;
  cursor: pointer;
}

.phone-card-3d:hover {
  transform: translateY(-6px) scale(1.02);
  box-shadow: 0 16px 30px -8px rgba(16, 185, 129, 0.2), 0 4px 8px -2px rgba(0, 0, 0, 0.05);
}

.phone-card-active {
  transform: translateY(-4px) scale(1.03);
  box-shadow: 0 18px 35px -8px rgba(16, 185, 129, 0.3), 0 0 0 2.5px #10B981;
}

/* Fresh Glassmorphism Card */
.glass-panel-light {
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(226, 232, 240, 0.95);
  box-shadow: 0 10px 25px -5px rgba(15, 23, 42, 0.04), 0 8px 10px -6px rgba(15, 23, 42, 0.02);
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}

.glass-panel-light:hover {
  border-color: rgba(16, 185, 129, 0.4);
  box-shadow: 0 20px 35px -10px rgba(16, 185, 129, 0.12), 0 1px 3px 0 rgba(0, 0, 0, 0.05);
}

/* Text Gradients */
.text-gradient-fresh {
  background: linear-gradient(135deg, #0F172A 15%, #065F46 65%, #059669 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.text-gradient-emerald-cyan {
  background: linear-gradient(135deg, #059669 0%, #0284C7 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Pulse Beacon */
@keyframes beacon-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(1.2);
  }
}

.animate-beacon {
  animation: beacon-pulse 2s ease-in-out infinite;
}

/* Fresh Glowing Button */
.btn-fresh-glow {
  background: linear-gradient(135deg, #10B981 0%, #059669 100%);
  box-shadow: 0 8px 20px -4px rgba(16, 185, 129, 0.4);
  transition: all 0.25s ease;
}

.btn-fresh-glow:hover {
  background: linear-gradient(135deg, #34D399 0%, #059669 100%);
  box-shadow: 0 12px 25px -4px rgba(16, 185, 129, 0.55);
  transform: translateY(-1px);
}

/* Float Animation */
@keyframes float-slow {
  0%, 100% {
    transform: translateY(0px);
  }
  50% {
    transform: translateY(-8px);
  }
}

.animate-float-slow {
  animation: float-slow 5s ease-in-out infinite;
}

/* Custom Canvas */
#fieldCanvas {
  cursor: crosshair;
  background-color: #F8FCF9;
  border-radius: 12px;
  touch-action: none;
}

/* Custom Scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: #F1F5F9;
}
::-webkit-scrollbar-thumb {
  background: #CBD5E1;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #10B981;
}

/* Blogger Post Content Styling */
.post-body {
  line-height: 1.8;
  color: #334155;
}
.post-body img {
  max-width: 100%;
  height: auto;
  border-radius: 1rem;
}
.post-body h1, .post-body h2, .post-body h3 {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  color: #0F172A;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
}
.post-body p {
  margin-bottom: 1.25em;
}
.post-body pre, .post-body code {
  font-family: 'JetBrains Mono', monospace;
  background-color: #F1F5F9;
  border-radius: 0.5rem;
  padding: 0.2rem 0.4rem;
  color: #047857;
}
.post-body pre code {
  padding: 0;
  background: transparent;
}
.post-body pre {
  padding: 1rem;
  overflow-x: auto;
}
.post-body blockquote {
  border-left: 4px solid #10B981;
  padding-left: 1rem;
  font-style: italic;
  color: #475569;
  background: rgba(209, 250, 229, 0.2);
  border-radius: 0 0.5rem 0.5rem 0;
  padding-top: 0.5rem;
  padding-bottom: 0.5rem;
}

/* Scroll-to-Top with Circular Progress Indicator */
.scroll-top-progress {
  position: fixed;
  bottom: 24px;
  right: 24px;
  width: 46px;
  height: 46px;
  background: #0F172A;
  border-radius: 50%;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  cursor: pointer;
  box-shadow: 0 10px 25px -5px rgba(5, 150, 105, 0.4), 0 4px 10px -2px rgba(15, 23, 42, 0.2);
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px) scale(0.9);
  transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.scroll-top-progress.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
}

.scroll-top-progress:hover {
  background: #059669;
  transform: translateY(-4px) scale(1.06);
  box-shadow: 0 16px 30px -5px rgba(5, 150, 105, 0.55);
}

.scroll-progress-svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 46px;
  height: 46px;
  transform: rotate(-90deg);
  pointer-events: none;
}

.scroll-progress-svg circle {
  fill: none;
  stroke-width: 3;
}

.scroll-progress-bg {
  stroke: rgba(255, 255, 255, 0.15);
}

.scroll-progress-bar {
  stroke: #10B981;
  stroke-dasharray: 138.2;
  stroke-dashoffset: 138.2;
  transition: stroke-dashoffset 0.1s linear;
}

.scroll-top-progress:hover .scroll-progress-bar {
  stroke: #FFFFFF;
}

body.script:
//
/**
 * PadiBot Autonomous Field Mission Simulator v3.0
 */
class FieldSimulator {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    if (!this.canvas) return;
    this.ctx = this.canvas.getContext('2d');

    this.points = [];
    this.waypoints = [];
    this.plantedSeedlings = [];
    this.isPolygonClosed = false;
    this.currentPattern = 'boustrophedon';

    this.rover = {
      x: 0,
      y: 0,
      targetIdx: 0,
      heading: 0,
      speed: 1.8,
      status: 'IDLE',
      distanceTraveled: 0,
      lastPlantPos: { x: 0, y: 0 },
      isDispenserActive: false
    };

    this.speedMultiplier = 1;
    this.rowSpacing = 28;
    this.plantSpacing = 16;
    this.safetyMargin = 22;
    this.animationFrameId = null;

    this.initCanvas();
    this.bindEvents();
    this.loadPreset(0);
    this.startLoop();
  }

  initCanvas() {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = rect.width * dpr;
    this.canvas.height = (rect.height || 420) * dpr;
    this.ctx.scale(dpr, dpr);
    this.width = rect.width;
    this.height = rect.height || 420;
  }

  bindEvents() {
    window.addEventListener('resize', () => {
      this.initCanvas();
      this.draw();
    });

    this.canvas.addEventListener('click', (e) => {
      if (this.rover.status === 'RUNNING') return;
      const rect = this.canvas.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      if (this.points.length >= 3) {
        const first = this.points[0];
        const dist = Math.hypot(x - first.x, y - first.y);
        if (dist < 25) {
          this.isPolygonClosed = true;
          this.generatePath();
          this.draw();
          return;
        }
      }

      if (!this.isPolygonClosed) {
        this.points.push({ x, y });
        if (this.points.length >= 3) {
          this.generatePath();
        }
        this.draw();
      }
    });
  }

  setPattern(patternName) {
    if (['boustrophedon', 'adaptive', 'spiral'].includes(patternName)) {
      this.currentPattern = patternName;
      this.stopMission();
      this.generatePath();
      this.draw();
    }
  }

  loadPreset(presetIdx) {
    this.stopMission();
    this.plantedSeedlings = [];
    const w = this.width || 600;
    const h = this.height || 400;
    const marginX = w * 0.12;
    const marginY = h * 0.15;

    if (presetIdx === 0) {
      this.points = [
        { x: marginX, y: marginY },
        { x: w - marginX, y: marginY },
        { x: w - marginX, y: h - marginY },
        { x: marginX, y: h - marginY }
      ];
    } else {
      this.points = [
        { x: marginX + 35, y: marginY + 25 },
        { x: w * 0.5, y: marginY },
        { x: w - marginX - 20, y: marginY + 45 },
        { x: w - marginX + 15, y: h * 0.55 },
        { x: w - marginX - 45, y: h - marginY },
        { x: w * 0.45, y: h - marginY - 15 },
        { x: marginX, y: h - marginY + 10 },
        { x: marginX - 15, y: h * 0.45 }
      ];
    }

    this.isPolygonClosed = true;
    this.generatePath();
    this.resetRoverPosition();
    this.updateHUD();
    this.draw();
  }

  clearField() {
    this.stopMission();
    this.points = [];
    this.waypoints = [];
    this.plantedSeedlings = [];
    this.isPolygonClosed = false;
    this.rover.status = 'IDLE';
    this.updateHUD();
    this.draw();
  }

  isPointInside(x, y, buffer = 0) {
    if (this.points.length < 3) return false;
    let inside = false;
    for (let i = 0, j = this.points.length - 1; i < this.points.length; j = i++) {
      const xi = this.points[i].x, yi = this.points[i].y;
      const xj = this.points[j].x, yj = this.points[j].y;
      const intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi);
      if (intersect) inside = !inside;
    }
    if (!inside) return false;

    if (buffer > 0) {
      for (let i = 0, j = this.points.length - 1; i < this.points.length; j = i++) {
        const p1 = this.points[j];
        const p2 = this.points[i];
        const dist = this.distToSegment({ x, y }, p1, p2);
        if (dist < buffer) return false;
      }
    }
    return true;
  }

  distToSegment(p, v, w) {
    const l2 = Math.hypot(v.x - w.x, v.y - w.y) ** 2;
    if (l2 === 0) return Math.hypot(p.x - v.x, p.y - v.y);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2;
    t = Math.max(0, Math.min(1, t));
    return Math.hypot(p.x - (v.x + t * (w.x - v.x)), p.y - (v.y + t * (w.y - v.y)));
  }

  isLineClear(p1, p2, samples = 18, buffer = 5) {
    for (let s = 0; s <= samples; s++) {
      const t = s / samples;
      const x = p1.x + t * (p2.x - p1.x);
      const y = p1.y + t * (p2.y - p1.y);
      if (!this.isPointInside(x, y, buffer)) return false;
    }
    return true;
  }

  findSafeTransitPath(pStart, pEnd) {
    if (this.isLineClear(pStart, pEnd, 18, 6)) {
      return [{ x: pEnd.x, y: pEnd.y, isPlanting: false }];
    }

    const n = this.points.length;
    let area = 0;
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      area += this.points[i].x * this.points[j].y - this.points[j].x * this.points[i].y;
    }
    const isCCW = area > 0;

    const innerNodes = [];
    for (let i = 0; i < n; i++) {
      const p1 = this.points[(i - 1 + n) % n];
      const p = this.points[i];
      const p2 = this.points[(i + 1) % n];

      const v1x = p.x - p1.x, v1y = p.y - p1.y;
      const v2x = p2.x - p.x, v2y = p2.y - p.y;
      const l1 = Math.hypot(v1x, v1y) || 1;
      const l2 = Math.hypot(v2x, v2y) || 1;

      let nx1 = isCCW ? -v1y / l1 : v1y / l1;
      let ny1 = isCCW ? v1x / l1 : -v1x / l1;
      let nx2 = isCCW ? -v2y / l2 : v2y / l2;
      let ny2 = isCCW ? v2x / l2 : -v2x / l2;

      let nx = (nx1 + nx2) / 2;
      let ny = (ny1 + ny2) / 2;
      const nlen = Math.hypot(nx, ny) || 1;
      nx /= nlen; ny /= nlen;

      const node = { x: p.x + nx * (this.safetyMargin + 4), y: p.y + ny * (this.safetyMargin + 4) };
      if (this.isPointInside(node.x, node.y, 6)) {
        innerNodes.push(node);
      }
    }

    const nodes = [pStart, ...innerNodes, pEnd];
    const N = nodes.length;
    const adj = Array.from({ length: N }, () => []);

    for (let i = 0; i < N; i++) {
      for (let j = i + 1; j < N; j++) {
        if (this.isLineClear(nodes[i], nodes[j], 14, 6)) {
          const d = Math.hypot(nodes[i].x - nodes[j].x, nodes[i].y - nodes[j].y);
          adj[i].push({ node: j, weight: d });
          adj[j].push({ node: i, weight: d });
        }
      }
    }

    const dist = new Array(N).fill(Infinity);
    const prev = new Array(N).fill(null);
    const visited = new Array(N).fill(false);
    dist[0] = 0;

    for (let count = 0; count < N; count++) {
      let u = -1;
      let minDist = Infinity;
      for (let i = 0; i < N; i++) {
        if (!visited[i] && dist[i] < minDist) {
          minDist = dist[i];
          u = i;
        }
      }

      if (u === -1 || u === N - 1) break;
      visited[u] = true;

      for (const edge of adj[u]) {
        if (!visited[edge.node] && dist[u] + edge.weight < dist[edge.node]) {
          dist[edge.node] = dist[u] + edge.weight;
          prev[edge.node] = u;
        }
      }
    }

    if (dist[N - 1] === Infinity) {
      return [{ x: pEnd.x, y: pEnd.y, isPlanting: false }];
    }

    const path = [];
    let curr = N - 1;
    while (curr !== null) {
      path.push(nodes[curr]);
      curr = prev[curr];
    }
    path.reverse();

    return path.slice(1).map(pt => ({ x: pt.x, y: pt.y, isPlanting: false }));
  }

  generatePath() {
    if (this.points.length < 3) return;

    if (this.currentPattern === 'spiral') {
      this.generateSpiralPath();
    } else if (this.currentPattern === 'adaptive') {
      this.generateAdaptivePath();
    } else {
      this.generateBoustrophedonPath();
    }

    this.resetRoverPosition();
  }

  generateBoustrophedonPath() {
    let minX = Infinity, maxX = -Infinity;
    this.points.forEach(p => {
      minX = Math.min(minX, p.x);
      maxX = Math.max(maxX, p.x);
    });

    const rawStrips = [];
    let stripId = 0;

    for (let x = minX + this.safetyMargin + 6; x <= maxX - this.safetyMargin - 6; x += this.rowSpacing) {
      const intersections = [];
      for (let i = 0, j = this.points.length - 1; i < this.points.length; j = i++) {
        const p1 = this.points[j];
        const p2 = this.points[i];
        if ((p1.x <= x && p2.x > x) || (p2.x <= x && p1.x > x)) {
          const y = p1.y + ((x - p1.x) / (p2.x - p1.x)) * (p2.y - p1.y);
          intersections.push(y);
        }
      }

      intersections.sort((a, b) => a - b);

      for (let k = 0; k < intersections.length; k += 2) {
        if (k + 1 < intersections.length) {
          const yStart = intersections[k] + this.safetyMargin;
          const yEnd = intersections[k + 1] - this.safetyMargin;

          if (yStart < yEnd) {
            const pA = { x, y: yStart };
            const pB = { x, y: yEnd };
            if (this.isLineClear(pA, pB, 12, 6)) {
              rawStrips.push({ id: stripId++, pA, pB });
            }
          }
        }
      }
    }

    if (rawStrips.length === 0) {
      this.waypoints = [];
      return;
    }

    const cells = [];
    const visitedStrips = new Set();

    for (let i = 0; i < rawStrips.length; i++) {
      if (visitedStrips.has(i)) continue;

      const cell = [rawStrips[i]];
      visitedStrips.add(i);

      let changed = true;
      while (changed) {
        changed = false;
        for (let j = 0; j < rawStrips.length; j++) {
          if (visitedStrips.has(j)) continue;
          const cand = rawStrips[j];

          for (const inCell of cell) {
            const dx = Math.abs(cand.pA.x - inCell.pA.x);
            if (dx <= this.rowSpacing * 1.35) {
              const yDist = Math.min(
                Math.abs(cand.pA.y - inCell.pA.y),
                Math.abs(cand.pB.y - inCell.pB.y),
                Math.abs(cand.pA.y - inCell.pB.y),
                Math.abs(cand.pB.y - inCell.pA.y)
              );
              if (yDist < 120 && (this.isLineClear(cand.pA, inCell.pA, 8, 5) || this.isLineClear(cand.pB, inCell.pB, 8, 5))) {
                cell.push(cand);
                visitedStrips.add(j);
                changed = true;
                break;
              }
            }
          }
        }
      }

      cell.sort((a, b) => a.pA.x - b.pA.x);
      cells.push(cell);
    }

    cells.sort((a, b) => a[0].pA.x - b[0].pA.x);

    const waypoints = [];
    let currentPos = cells[0][0].pA;
    waypoints.push({ x: currentPos.x, y: currentPos.y, isPlanting: false });

    for (const cell of cells) {
      let isTopToBottom = true;

      const distToTop = Math.hypot(currentPos.x - cell[0].pA.x, currentPos.y - cell[0].pA.y);
      const distToBot = Math.hypot(currentPos.x - cell[0].pB.x, currentPos.y - cell[0].pB.y);

      let targetEntry = distToTop <= distToBot ? cell[0].pA : cell[0].pB;
      isTopToBottom = (targetEntry === cell[0].pA);

      if (Math.hypot(currentPos.x - targetEntry.x, currentPos.y - targetEntry.y) > 6) {
        const transits = this.findSafeTransitPath(currentPos, targetEntry);
        transits.forEach(wp => waypoints.push(wp));
      }

      for (let s = 0; s < cell.length; s++) {
        const strip = cell[s];
        const startPt = isTopToBottom ? strip.pA : strip.pB;
        const endPt = isTopToBottom ? strip.pB : strip.pA;

        if (Math.hypot(currentPos.x - startPt.x, currentPos.y - startPt.y) > 4) {
          if (this.isLineClear(currentPos, startPt, 10, 5)) {
            waypoints.push({ x: startPt.x, y: startPt.y, isPlanting: false });
          } else {
            const safeTransits = this.findSafeTransitPath(currentPos, startPt);
            safeTransits.forEach(wp => waypoints.push(wp));
          }
        }

        waypoints.push({ x: startPt.x, y: startPt.y, isPlanting: true });
        waypoints.push({ x: endPt.x, y: endPt.y, isPlanting: true });

        currentPos = endPt;
        isTopToBottom = !isTopToBottom;
      }
    }

    this.waypoints = waypoints;
  }

  generateAdaptivePath() {
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    this.points.forEach(p => {
      minX = Math.min(minX, p.x);
      maxX = Math.max(maxX, p.x);
      minY = Math.min(minY, p.y);
      maxY = Math.max(maxY, p.y);
    });

    const angle = Math.PI / 6;
    const cosA = Math.cos(angle);
    const sinA = Math.sin(angle);
    const perpX = -sinA;
    const perpY = cosA;

    const projections = this.points.map(p => p.x * perpX + p.y * perpY);
    const minProj = Math.min(...projections);
    const maxProj = Math.max(...projections);

    const rawStrips = [];
    let stripId = 0;

    for (let proj = minProj + this.safetyMargin + 6; proj <= maxProj - this.safetyMargin - 6; proj += this.rowSpacing) {
      const intersections = [];
      const n = this.points.length;

      for (let i = 0; i < n; i++) {
        const p1 = this.points[i];
        const p2 = this.points[(i + 1) % n];

        const pr1 = p1.x * perpX + p1.y * perpY;
        const pr2 = p2.x * perpX + p2.y * perpY;

        if ((pr1 <= proj && pr2 > proj) || (pr2 <= proj && pr1 > proj)) {
          const t = (proj - pr1) / (pr2 - pr1);
          const ix = p1.x + t * (p2.x - p1.x);
          const iy = p1.y + t * (p2.y - p1.y);
          const along = ix * cosA + iy * sinA;
          intersections.push({ x: ix, y: iy, along });
        }
      }

      intersections.sort((a, b) => a.along - b.along);

      for (let k = 0; k < intersections.length; k += 2) {
        if (k + 1 < intersections.length) {
          const i1 = intersections[k];
          const i2 = intersections[k + 1];

          const dx = i2.x - i1.x;
          const dy = i2.y - i1.y;
          const len = Math.hypot(dx, dy);

          if (len > this.safetyMargin * 2) {
            const ux = dx / len;
            const uy = dy / len;
            const pA = { x: i1.x + ux * this.safetyMargin, y: i1.y + uy * this.safetyMargin };
            const pB = { x: i2.x - ux * this.safetyMargin, y: i2.y - uy * this.safetyMargin };

            if (this.isLineClear(pA, pB, 12, 6)) {
              rawStrips.push({ id: stripId++, pA, pB, proj });
            }
          }
        }
      }
    }

    if (rawStrips.length === 0) {
      this.generateBoustrophedonPath();
      return;
    }

    const waypoints = [];
    let currentPos = rawStrips[0].pA;
    waypoints.push({ x: currentPos.x, y: currentPos.y, isPlanting: false });

    let isForward = true;
    for (let s = 0; s < rawStrips.length; s++) {
      const strip = rawStrips[s];
      const startPt = isForward ? strip.pA : strip.pB;
      const endPt = isForward ? strip.pB : strip.pA;

      if (Math.hypot(currentPos.x - startPt.x, currentPos.y - startPt.y) > 4) {
        if (this.isLineClear(currentPos, startPt, 10, 5)) {
          waypoints.push({ x: startPt.x, y: startPt.y, isPlanting: false });
        } else {
          const transits = this.findSafeTransitPath(currentPos, startPt);
          transits.forEach(wp => waypoints.push(wp));
        }
      }

      waypoints.push({ x: startPt.x, y: startPt.y, isPlanting: true });
      waypoints.push({ x: endPt.x, y: endPt.y, isPlanting: true });

      currentPos = endPt;
      isForward = !isForward;
    }

    this.waypoints = waypoints;
  }

  generateSpiralPath() {
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    this.points.forEach(p => {
      minX = Math.min(minX, p.x);
      maxX = Math.max(maxX, p.x);
      minY = Math.min(minY, p.y);
      maxY = Math.max(maxY, p.y);
    });

    const cx = (minX + maxX) / 2;
    const cy = (minY + maxY) / 2;

    const wSpan = maxX - minX;
    const hSpan = maxY - minY;
    const maxRadius = Math.min(wSpan, hSpan) / 2 - this.safetyMargin;

    const step = this.rowSpacing;
    const numRings = Math.max(2, Math.floor(maxRadius / step));

    const waypoints = [];
    let lastPt = { x: cx, y: cy };
    waypoints.push({ x: cx, y: cy, isPlanting: false });

    for (let i = 1; i <= numRings; i++) {
      const rx = i * step * (wSpan / (hSpan || 1));
      const ry = i * step;

      const ringCorners = [
        { x: cx + rx, y: lastPt.y },
        { x: cx + rx, y: cy - ry },
        { x: cx - rx, y: cy - ry },
        { x: cx - rx, y: cy + ry },
        { x: cx + rx, y: cy + ry }
      ];

      for (const corner of ringCorners) {
        if (this.isPointInside(corner.x, corner.y, 6)) {
          if (this.isLineClear(lastPt, corner, 8, 4)) {
            waypoints.push({ x: corner.x, y: corner.y, isPlanting: true });
            lastPt = corner;
          }
        }
      }
    }

    this.waypoints = waypoints.length > 2 ? waypoints : [];
    if (this.waypoints.length === 0) {
      this.generateBoustrophedonPath();
    }
  }

  resetRoverPosition() {
    if (this.waypoints.length > 0) {
      this.rover.x = this.waypoints[0].x;
      this.rover.y = this.waypoints[0].y;
      this.rover.targetIdx = 1;
      this.rover.lastPlantPos = { x: this.rover.x, y: this.rover.y };
      this.rover.distanceTraveled = 0;
      this.rover.heading = Math.PI / 2;
      this.rover.isDispenserActive = false;
    }
  }

  startMission() {
    if (this.waypoints.length === 0) return;
    if (this.rover.status === 'COMPLETED' || this.rover.status === 'ESTOP') {
      this.resetRoverPosition();
      this.plantedSeedlings = [];
    }
    this.rover.status = 'RUNNING';
    this.updateHUD();
  }

  pauseMission() {
    if (this.rover.status === 'RUNNING') {
      this.rover.status = 'PAUSED';
      this.updateHUD();
    }
  }

  emergencyStop() {
    this.rover.status = 'ESTOP';
    this.updateHUD();
  }

  stopMission() {
    this.rover.status = 'IDLE';
    this.resetRoverPosition();
    this.plantedSeedlings = [];
    this.updateHUD();
  }

  setSpeedMultiplier(multiplier) {
    this.speedMultiplier = multiplier;
  }

  updateRover() {
    if (this.rover.status !== 'RUNNING') return;
    if (this.rover.targetIdx >= this.waypoints.length) {
      this.rover.status = 'COMPLETED';
      this.rover.isDispenserActive = false;
      this.updateHUD();
      return;
    }

    const target = this.waypoints[this.rover.targetIdx];
    const dx = target.x - this.rover.x;
    const dy = target.y - this.rover.y;
    const dist = Math.hypot(dx, dy);

    this.rover.heading = Math.atan2(dy, dx);
    const step = this.rover.speed * this.speedMultiplier;

    if (dist <= step) {
      this.rover.x = target.x;
      this.rover.y = target.y;
      this.rover.targetIdx++;
    } else {
      this.rover.x += (dx / dist) * step;
      this.rover.y += (dy / dist) * step;
    }

    this.rover.distanceTraveled += step;

    const isPlantingSegment = target.isPlanting === true;
    const isSafeInside = this.isPointInside(this.rover.x, this.rover.y, 8);

    this.rover.isDispenserActive = isPlantingSegment && isSafeInside;

    if (this.rover.isDispenserActive) {
      const distSinceLastPlant = Math.hypot(
        this.rover.x - this.rover.lastPlantPos.x,
        this.rover.y - this.rover.lastPlantPos.y
      );

      if (distSinceLastPlant >= this.plantSpacing) {
        this.plantedSeedlings.push({ x: this.rover.x, y: this.rover.y });
        this.rover.lastPlantPos = { x: this.rover.x, y: this.rover.y };
        this.updateHUD();
      }
    }
  }

  updateHUD() {
    const statusEl = document.getElementById('simStatusBadge');
    const seedlingsCountEl = document.getElementById('simSeedlingCount');
    const progressEl = document.getElementById('simProgressPct');
    const areaEl = document.getElementById('simAreaCovered');
    const coordsEl = document.getElementById('simRoverCoords');
    const speedEl = document.getElementById('simRoverSpeed');

    if (statusEl) {
      statusEl.textContent = this.rover.status;
      if (this.rover.status === 'RUNNING') {
        statusEl.className = 'px-2.5 py-1 rounded text-xs font-mono bg-emerald-100 text-emerald-700 border border-emerald-300 font-semibold animate-pulse';
      } else if (this.rover.status === 'ESTOP') {
        statusEl.className = 'px-2.5 py-1 rounded text-xs font-mono bg-red-100 text-red-700 border border-red-300 font-bold';
      } else if (this.rover.status === 'COMPLETED') {
        statusEl.className = 'px-2.5 py-1 rounded text-xs font-mono bg-cyan-100 text-cyan-700 border border-cyan-300 font-semibold';
      } else {
        statusEl.className = 'px-2.5 py-1 rounded text-xs font-mono bg-slate-100 text-slate-600 border border-slate-300';
      }
    }

    if (seedlingsCountEl) seedlingsCountEl.textContent = this.plantedSeedlings.length.toLocaleString('id-ID');

    const pct = this.waypoints.length > 0 ? Math.min(100, Math.round((this.rover.targetIdx / this.waypoints.length) * 100)) : 0;
    if (progressEl) progressEl.textContent = `${pct}%`;

    const areaM2 = (this.plantedSeedlings.length * 0.04).toFixed(1);
    if (areaEl) areaEl.textContent = `${areaM2} m²`;

    if (coordsEl) {
      const lat = (-6.914744 + (this.rover.y * 0.000005)).toFixed(6);
      const lon = (107.609810 + (this.rover.x * 0.000005)).toFixed(6);
      coordsEl.textContent = `${lat}, ${lon}`;
    }

    if (speedEl) {
      const speedKmH = this.rover.status === 'RUNNING' ? (1.4 * this.speedMultiplier).toFixed(1) : '0.0';
      speedEl.textContent = `${speedKmH} km/h`;
    }
  }

  draw() {
    this.ctx.clearRect(0, 0, this.width, this.height);

    this.ctx.fillStyle = '#F8FCF9';
    this.ctx.fillRect(0, 0, this.width, this.height);

    this.drawBackgroundGrid();

    if (this.points.length > 0) {
      this.ctx.beginPath();
      this.ctx.moveTo(this.points[0].x, this.points[0].y);
      for (let i = 1; i < this.points.length; i++) {
        this.ctx.lineTo(this.points[i].x, this.points[i].y);
      }
      if (this.isPolygonClosed) {
        this.ctx.closePath();
        this.ctx.fillStyle = 'rgba(16, 185, 129, 0.10)';
        this.ctx.fill();
      }

      this.ctx.strokeStyle = '#059669';
      this.ctx.lineWidth = 2.5;
      this.ctx.stroke();

      this.points.forEach((p, idx) => {
        this.ctx.beginPath();
        this.ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
        this.ctx.fillStyle = idx === 0 ? '#0284C7' : '#10B981';
        this.ctx.fill();
        this.ctx.strokeStyle = '#FFFFFF';
        this.ctx.lineWidth = 2;
        this.ctx.stroke();

        this.ctx.fillStyle = '#1E293B';
        this.ctx.font = 'bold 11px JetBrains Mono';
        this.ctx.fillText(`P${idx + 1}`, p.x + 8, p.y - 6);
      });
    }

    if (this.waypoints.length > 1) {
      this.ctx.beginPath();
      this.ctx.moveTo(this.waypoints[0].x, this.waypoints[0].y);
      for (let i = 1; i < this.waypoints.length; i++) {
        const wp1 = this.waypoints[i - 1];
        const wp2 = this.waypoints[i];
        if (this.isLineClear(wp1, wp2, 8, 2)) {
          this.ctx.lineTo(wp2.x, wp2.y);
        } else {
          this.ctx.moveTo(wp2.x, wp2.y);
        }
      }
      this.ctx.strokeStyle = '#0284C7';
      this.ctx.lineWidth = 2.0;
      this.ctx.setLineDash([3, 4]);
      this.ctx.stroke();
      this.ctx.setLineDash([]);
    }

    this.plantedSeedlings.forEach(s => {
      this.ctx.beginPath();
      this.ctx.arc(s.x, s.y, 3, 0, Math.PI * 2);
      this.ctx.fillStyle = '#16A34A';
      this.ctx.fill();
    });

    if (this.rover.status !== 'IDLE' || this.waypoints.length > 0) {
      this.drawRover(this.rover.x, this.rover.y, this.rover.heading);
    }
  }

  drawBackgroundGrid() {
    this.ctx.strokeStyle = 'rgba(16, 185, 129, 0.08)';
    this.ctx.lineWidth = 1;
    const step = 30;
    for (let x = 0; x < this.width; x += step) {
      this.ctx.beginPath();
      this.ctx.moveTo(x, 0);
      this.ctx.lineTo(x, this.height);
      this.ctx.stroke();
    }
    for (let y = 0; y < this.height; y += step) {
      this.ctx.beginPath();
      this.ctx.moveTo(0, y);
      this.ctx.lineTo(this.width, y);
      this.ctx.stroke();
    }
  }

  drawRover(x, y, heading) {
    this.ctx.save();
    this.ctx.translate(x, y);
    this.ctx.rotate(heading);

    if (this.rover.status === 'RUNNING') {
      const gradient = this.ctx.createRadialGradient(0, 0, 5, 25, 0, 48);
      gradient.addColorStop(0, 'rgba(2, 132, 199, 0.45)');
      gradient.addColorStop(1, 'rgba(2, 132, 199, 0)');
      this.ctx.beginPath();
      this.ctx.moveTo(0, 0);
      this.ctx.arc(0, 0, 48, -Math.PI / 4, Math.PI / 4);
      this.ctx.closePath();
      this.ctx.fillStyle = gradient;
      this.ctx.fill();
    }

    this.ctx.fillStyle = '#FFFFFF';
    this.ctx.strokeStyle = '#059669';
    this.ctx.lineWidth = 2;
    this.ctx.fillRect(-13, -10, 26, 20);
    this.ctx.strokeRect(-13, -10, 26, 20);

    this.ctx.fillStyle = '#334155';
    this.ctx.fillRect(-15, -14, 30, 4);
    this.ctx.fillRect(-15, 10, 30, 4);

    this.ctx.beginPath();
    this.ctx.arc(0, 0, 4, 0, Math.PI * 2);
    this.ctx.fillStyle = this.rover.status === 'ESTOP' ? '#EF4444' : '#10B981';
    this.ctx.fill();

    this.ctx.strokeStyle = this.rover.isDispenserActive ? '#15803D' : '#94A3B8';
    this.ctx.lineWidth = 2.5;
    this.ctx.beginPath();
    this.ctx.moveTo(-13, 0);
    this.ctx.lineTo(-19, 0);
    this.ctx.stroke();

    this.ctx.restore();
  }

  startLoop() {
    const loop = () => {
      this.updateRover();
      this.draw();
      this.animationFrameId = requestAnimationFrame(loop);
    };
    loop();
  }
}

window.FieldSimulator = FieldSimulator;

/**
 * UI Event Controllers
 */
document.addEventListener('DOMContentLoaded', () => {
  // Initialize Simulator
  if (document.getElementById('fieldCanvas')) {
    const sim = new window.FieldSimulator('fieldCanvas');

    const btnStart = document.getElementById('btnSimStart');
    const btnPause = document.getElementById('btnSimPause');
    const btnEstop = document.getElementById('btnSimEstop');
    const btnClear = document.getElementById('btnSimClear');
    const btnPresetRect = document.getElementById('btnPresetRect');
    const btnPresetContour = document.getElementById('btnPresetContour');
    const speedBtns = document.querySelectorAll('.sim-speed-btn');

    if (btnStart) btnStart.addEventListener('click', () => sim.startMission());
    if (btnPause) btnPause.addEventListener('click', () => sim.pauseMission());
    if (btnEstop) btnEstop.addEventListener('click', () => sim.emergencyStop());
    if (btnClear) btnClear.addEventListener('click', () => sim.clearField());

    if (btnPresetRect) {
      btnPresetRect.addEventListener('click', () => {
        sim.loadPreset(0);
        btnPresetRect.classList.add('bg-emerald-600', 'text-white', 'border-emerald-600', 'shadow-md');
        btnPresetRect.classList.remove('bg-white', 'text-slate-700', 'border-slate-300');
        if (btnPresetContour) {
          btnPresetContour.classList.remove('bg-emerald-600', 'text-white', 'border-emerald-600', 'shadow-md');
          btnPresetContour.classList.add('bg-white', 'text-slate-700', 'border-slate-300');
        }
      });
    }

    if (btnPresetContour) {
      btnPresetContour.addEventListener('click', () => {
        sim.loadPreset(1);
        btnPresetContour.classList.add('bg-emerald-600', 'text-white', 'border-emerald-600', 'shadow-md');
        btnPresetContour.classList.remove('bg-white', 'text-slate-700', 'border-slate-300');
        if (btnPresetRect) {
          btnPresetRect.classList.remove('bg-emerald-600', 'text-white', 'border-emerald-600', 'shadow-md');
          btnPresetRect.classList.add('bg-white', 'text-slate-700', 'border-slate-300');
        }
      });
    }

    const patternBtns = document.querySelectorAll('.pattern-select-btn');
    patternBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        patternBtns.forEach(b => {
          b.classList.remove('bg-emerald-600', 'text-white', 'border-emerald-600');
          b.classList.add('bg-white', 'text-slate-700', 'border-slate-300');
        });
        btn.classList.add('bg-emerald-600', 'text-white', 'border-emerald-600');
        btn.classList.remove('bg-white', 'text-slate-700', 'border-slate-300');
        const pattern = btn.getAttribute('data-pattern') || 'boustrophedon';
        sim.setPattern(pattern);
      });
    });

    speedBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        speedBtns.forEach(b => {
          b.classList.remove('bg-emerald-600', 'text-white', 'border-emerald-600');
          b.classList.add('bg-white', 'text-slate-700', 'border-slate-200');
        });
        btn.classList.add('bg-emerald-600', 'text-white', 'border-emerald-600');
        btn.classList.remove('bg-white', 'text-slate-700', 'border-slate-200');
        const speed = parseFloat(btn.getAttribute('data-speed') || '1');
        sim.setSpeedMultiplier(speed);
      });
    });
  }

  // 3D Card Tilt Engine
  const tiltCards = document.querySelectorAll('.tilt-card');
  tiltCards.forEach(card => {
    card.addEventListener('mousemove', (e) => {
      const rect = card.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      const centerX = rect.width / 2;
      const centerY = rect.height / 2;

      const rotateX = ((y - centerY) / centerY) * -9;
      const rotateY = ((x - centerX) / centerX) * 9;

      card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateY(-4px)`;
    });

    card.addEventListener('mouseleave', () => {
      card.style.transform = 'perspective(1000px) rotateX(0deg) rotateY(0deg) translateY(0px)';
    });
  });

  // 3D Phone App Screen Showcase
  const phoneCards = document.querySelectorAll('.phone-card-3d');
  const mainScreenImg = document.getElementById('featuredScreenImg');
  const mainScreenTitle = document.getElementById('featuredScreenTitle');
  const mainScreenBadge = document.getElementById('featuredScreenBadge');
  const mainScreenDesc = document.getElementById('featuredScreenDesc');
  const mainScreenSpecs = document.getElementById('featuredScreenSpecs');

  const screenDetails = {
    'dashboard': {
      title: 'Dashboard Kontrol Utama',
      badge: 'Layar 1 • Status Real-Time',
      img: 'data:image/webp;base64,',
      desc: 'Menampilkan status telemetri robot secara komprehensif: persentase baterai 82%, kualitas sinyal GPS RTK, kecepatan bergerak 6.0 m/s, serta mode penanaman AUTO. Dilengkapi tombol cepat untuk mulai pemetaan, memilih sawah, dan kontrol manual.',
      bullets: ['Visual indikator status koneksi real-time', 'Speedometer & Battery gauge', 'Akses cepat ke 3 mode operasional']
    },
    'mapping': {
      title: 'Pemetaan Batas Sawah Presisi',
      badge: 'Layar 2 • Boundary GPS',
      img: 'data:image/webp;base64,',
      desc: 'Petani menandai titik pematang sawah langsung di peta satelit. Sistem mencatat jarak batas keliling (120 m) dengan akurasi sentimeter (3 cm) dan membentuk poligon sawah otomatis.',
      bullets: ['Mode perekaman titik demi titik (Point & Polygon)', 'Akurasi pembacaan GPS RTK hingga 3 cm', 'Penghitung jarak keliling & luas otomatis']
    },
    'settings': {
      title: 'Pengaturan Parameter Tanam',
      badge: 'Layar 3 • Konfigurasi Agronomi',
      img: 'data:image/webp;base64,',
      desc: 'Kustomisasi jarak tanam antar-baris (30 cm), jarak antar-tanaman (20 cm), lebar efektif kerja mesin (120 cm), kecepatan operasi (0.8 m/s), serta jarak putar headland (1.5 m).',
      bullets: ['Pengaturan jarak tanam Jajar Legowo & Konvensional', 'Pengaturan kecepatan dorong & kedalaman tanam', 'Tombol instan Generate Jalur Tanam']
    },
    'path_gen': {
      title: 'Kalkulasi Jalur Otomatis (Boustrophedon)',
      badge: 'Layar 4 • Path Planning',
      img: 'data:image/webp;base64,',
      desc: 'Algoritma cerdas menghitung rute zig-zag bolak-balik (lawnmower) di dalam batas sawah, lengkap dengan zona putar headland dan penanda titik awal (Start) & akhir (End).',
      bullets: ['Optimasi rute minim lintasan tumpang tindih', 'Visualisasi zona putar traktor di tepi sawah', 'Estimasi waktu dan bibit yang dibutuhkan']
    },
    'auto_mode': {
      title: 'Eksekusi Misi Otonom',
      badge: 'Layar 5 • Live Monitoring',
      img: 'data:image/webp;base64,',
      desc: 'Pantau pergerakan robot secara real-time saat menanam padi di sawah. Menampilkan persentase progres (72%), luas area yang selesai (1.240 m²), sisa area (480 m²), dan tombol Pause/Stop darurat.',
      bullets: ['Live tracking posisi traktor di atas peta', 'Real-time calculation luas selesai vs sisa', 'Kontrol Start, Pause, Resume, dan Emergency Stop']
    },
    'report': {
      title: 'Riwayat & Laporan Hasil Tanam',
      badge: 'Layar 6 • Laporan Lengkap',
      img: 'data:image/webp;base64,',
      desc: 'Log historis setiap misi tanam tersimpan di SQLite lokal. Menyajikan laporan luas total lahan (2.000 m²), area tertanam sukses (1.950 m²), area terlewat (50 m²), dan durasi pengerjaan (1 jam 32 menit).',
      bullets: ['Laporan detail efisiensi cakupan lahan', 'Peta jejak historis penanaman lengkap', 'Tersimpan 100% offline di memori smartphone']
    }
  };

  phoneCards.forEach(card => {
    card.addEventListener('click', () => {
      const key = card.getAttribute('data-screen-key');
      const data = screenDetails[key];
      if (!data) return;

      phoneCards.forEach(c => c.classList.remove('phone-card-active', 'ring-4', 'ring-emerald-500'));
      card.classList.add('phone-card-active', 'ring-4', 'ring-emerald-500');

      if (mainScreenImg) {
        mainScreenImg.src = data.img;
        mainScreenImg.classList.add('scale-95');
        setTimeout(() => mainScreenImg.classList.remove('scale-95'), 200);
      }
      if (mainScreenTitle) mainScreenTitle.textContent = data.title;
      if (mainScreenBadge) mainScreenBadge.textContent = data.badge;
      if (mainScreenDesc) mainScreenDesc.textContent = data.desc;

      if (mainScreenSpecs) {
        mainScreenSpecs.innerHTML = data.bullets.map(b => `
          <li class="flex items-center space-x-2 text-xs font-mono text-slate-700">
            <span class="w-2 h-2 rounded-full bg-emerald-500 flex-shrink-0"></span>
            <span>${b}</span>
          </li>
        `).join('');
      }
    });
  });

  // 3D Schematic Hotspots
  const hotspotData = {
    'gps': {
      title: 'Antena GNSS RTK Multi-Konstelasi',
      badge: 'Centimeter Precision Navigation',
      desc: 'Terpasang pada tiang atas robot untuk menerima sinyal satelit GPS, GLONASS, Galileo, dan BeiDou dengan akurasi posisi tanam hingga ±2.5 cm di area sawah terbuka.',
      specs: ['Up to 10 Hz Update Rate', 'High Sensitivity -167 dBm', 'Active Ceramic Patch Antenna', 'Dukungan Koreksi RTCM 3.X']
    },
    'mcu': {
      title: 'Panel Kontrol Arduino Mega 2560 & ESP32',
      badge: 'Main Processing Unit',
      desc: 'Otak utama robot yang memproses navigasi otonom, kendali motor driver, encoder roda traktor, dan telemetri nirkabel ke smartphone.',
      specs: ['16 MHz ATmega2560 Master Core', 'Dual-Core 240MHz ESP32 WiFi/BLE', '54 Digital I/O (15 PWM pins)', '4 Hardware UART Serial Ports']
    },
    'estop': {
      title: 'Emergency Stop Fisik (Hardwired)',
      badge: 'Fail-Safe Safety System',
      desc: 'Tombol merah darurat fisik di bagian atas mesin yang langsung memutus aliran daya motor penggerak dalam tempo <15 milidetik saat ditekan.',
      specs: ['Direct Cut-Off Power Relay', 'Tahan percikan air & lumpur sawah IP65', 'Terhubung ke software alarm Android']
    },
    'planter': {
      title: 'Mekanisme Tanam & Tray Bibit Padi',
      badge: 'Automated Seedling Feeder',
      desc: 'Baki penampung bibit dengan lengan capit rotary otomatis yang menancapkan bibit pada kedalaman 2-4 cm sesuai jarak jajar legowo yang diatur.',
      specs: ['4-Row Simultaneous Planting', 'Depth Setting: 2-5 cm Presisi', 'Spacing: 15-30 cm Auto-adjust', 'Sensor Anti-Macet Bibit']
    },
    'motor': {
      title: 'Motor Penggerak Track & Kemudi IBT-2',
      badge: 'Heavy-Duty Mud Traversing',
      desc: 'Ditenagai motor DC bertorsi tinggi dengan driver H-Bridge IBT-2 (43A per channel), mampu melintasi lumpur sawah dalam tanpa selip.',
      specs: ['Dual IBT-2 43A High-Current Driver', 'High-Torque Planetary Gearbox', 'Track Karet Anti-Selip Lumpur', 'Kemudi Diferensial Presisi']
    }
  };

  const hotspotBtns = document.querySelectorAll('.hotspot-btn');
  const inspectorTitle = document.getElementById('inspectorTitle');
  const inspectorBadge = document.getElementById('inspectorBadge');
  const inspectorDesc = document.getElementById('inspectorDesc');
  const inspectorSpecs = document.getElementById('inspectorSpecs');

  hotspotBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const key = btn.getAttribute('data-hotspot');
      const data = hotspotData[key];
      if (!data) return;

      hotspotBtns.forEach(b => {
        b.classList.remove('ring-4', 'ring-emerald-400', 'bg-emerald-600');
        b.classList.add('bg-emerald-500');
      });
      btn.classList.add('ring-4', 'ring-emerald-400', 'bg-emerald-600');

      if (inspectorTitle) inspectorTitle.textContent = data.title;
      if (inspectorBadge) inspectorBadge.textContent = data.badge;
      if (inspectorDesc) inspectorDesc.textContent = data.desc;

      if (inspectorSpecs) {
        inspectorSpecs.innerHTML = data.specs.map(s => `
          <li class="flex items-center space-x-2 text-xs font-mono text-slate-700">
            <span class="w-2 h-2 rounded-full bg-emerald-500 flex-shrink-0"></span>
            <span>${s}</span>
          </li>
        `).join('');
      }
    });
  });

  // Telemetry Live Update
  setInterval(() => {
    const battVoltsEl = document.getElementById('telemBattVolt');
    const motorTempEl = document.getElementById('telemMotorTemp');
    const pingEl = document.getElementById('telemPing');

    if (battVoltsEl) {
      const v = (24.6 + Math.random() * 0.4).toFixed(1);
      battVoltsEl.textContent = `${v}V`;
    }
    if (motorTempEl) {
      const t = (32 + Math.random() * 2).toFixed(1);
      motorTempEl.textContent = `${t}°C`;
    }
    if (pingEl) {
      const p = Math.floor(12 + Math.random() * 6);
      pingEl.textContent = `${p}ms`;
    }
  }, 2500);

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const header = item.querySelector('.faq-header');
    const content = item.querySelector('.faq-content');
    const icon = item.querySelector('.faq-icon');

    if (header && content) {
      header.addEventListener('click', () => {
        const isOpen = !content.classList.contains('hidden');
        faqItems.forEach(other => {
          other.querySelector('.faq-content')?.classList.add('hidden');
          other.querySelector('.faq-icon')?.classList.remove('rotate-180');
        });

        if (!isOpen) {
          content.classList.remove('hidden');
          if (icon) icon.classList.add('rotate-180');
        }
      });
    }
  });

  // Toast Notification for Downloads
  const downloadBtns = document.querySelectorAll('.download-trigger-btn');
  const toast = document.getElementById('toastNotification');

  downloadBtns.forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      if (toast) {
        toast.classList.remove('translate-y-24', 'opacity-0');
        toast.classList.add('translate-y-0', 'opacity-100');
        setTimeout(() => {
          toast.classList.add('translate-y-24', 'opacity-0');
          toast.classList.remove('translate-y-0', 'opacity-100');
        }, 4000);
      }
    });
  });

  // Mobile Menu
  const mobileMenuBtn = document.getElementById('mobileMenuBtn');
  const mobileMenu = document.getElementById('mobileMenu');
  if (mobileMenuBtn && mobileMenu) {
    mobileMenuBtn.addEventListener('click', () => {
      mobileMenu.classList.toggle('hidden');
    });
  }

  // Navbar Scrollspy
  const sectionIds = ['overview', 'app-showcase', 'simulator', 'schematics', 'patterns', 'blog-section', 'faq'];
  const desktopNavLinks = document.querySelectorAll('.nav-link');
  const mobileNavLinks = document.querySelectorAll('.mobile-nav-link');

  function updateActiveNavLink() {
    const scrollPosition = window.scrollY + 160;
    let currentSectionId = 'overview';

    if (window.scrollY < 200) {
      currentSectionId = 'overview';
    } else {
      sectionIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) {
          const top = el.offsetTop;
          const height = el.offsetHeight;
          if (scrollPosition >= top && scrollPosition < top + height) {
            currentSectionId = id;
          }
        }
      });

      if ((window.innerHeight + window.scrollY) >= (document.documentElement.scrollHeight - 60)) {
        currentSectionId = 'faq';
      }
    }

    desktopNavLinks.forEach(link => {
      if (link.getAttribute('data-section') === currentSectionId) {
        link.classList.add('nav-link-active');
        link.classList.remove('nav-link-inactive');
      } else {
        link.classList.remove('nav-link-active');
        link.classList.add('nav-link-inactive');
      }
    });

    mobileNavLinks.forEach(link => {
      if (link.getAttribute('data-section') === currentSectionId) {
        link.classList.add('nav-link-active');
        link.classList.remove('nav-link-inactive');
      } else {
        link.classList.remove('nav-link-active');
        link.classList.add('nav-link-inactive');
      }
    });
  }

  window.addEventListener('scroll', updateActiveNavLink, { passive: true });
  updateActiveNavLink();


  // Scroll-to-Top Circular Progress Indicator (adigue style)
  const scrollTopBtn = document.getElementById('scrollTopBtn');
  const scrollProgressBar = document.getElementById('scrollProgressBar');
  const circumference = 2 * Math.PI * 22;

  if (scrollTopBtn && scrollProgressBar) {
    scrollProgressBar.style.strokeDasharray = circumference;
    scrollProgressBar.style.strokeDashoffset = circumference;

    window.addEventListener('scroll', () => {
      const scrollY = window.scrollY || window.pageYOffset;
      const docHeight = document.documentElement.scrollHeight - window.innerHeight;
      const scrollFraction = docHeight > 0 ? scrollY / docHeight : 0;

      if (scrollY > 280) {
        scrollTopBtn.classList.add('active');
      } else {
        scrollTopBtn.classList.remove('active');
      }

      const offset = circumference - (scrollFraction * circumference);
      scrollProgressBar.style.strokeDashoffset = offset;
    }, { passive: true });

    scrollTopBtn.addEventListener('click', () => {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    });
  }

  // Initialize Lucide Icons
  if (window.lucide) {
    lucide.createIcons();
  }
});
//
